/**
 * Helper function to retrieve full archetype book detail for a driver number (1 to 9)
 */
export function getDriverArchetypeDetail(driverNum: number): DriverArchetypeDetail {
  const reduced = ((driverNum - 1) % 9) + 1;
  return DRIVER_ARCHETYPES_DATABASE[reduced] || DRIVER_ARCHETYPES_DATABASE[1];
}
